import json
import re
import shutil
import subprocess
import tempfile
import unittest
from pathlib import Path

TARGET = Path(__file__).resolve().parent / "solar-system.html"
MODEL_ID = "orbit-model"

DRIVER = r"""
import { positions } from './model.mjs';

const DT = 0.01;
const SPAN = 150;
const TWO_PI = Math.PI * 2;

function wrap(a) {
  while (a > Math.PI) a -= TWO_PI;
  while (a < -Math.PI) a += TWO_PI;
  return a;
}

const first = positions(0);
const meta = new Map();
for (const b of first) {
  meta.set(String(b.id), {
    id: String(b.id),
    kind: String(b.kind),
    parent: (b.parent === undefined || b.parent === null) ? null : String(b.parent),
    r: Number(b.r),
    rmin: Infinity, rmax: -Infinity, dsum: 0,
    cum: 0, prevA: null, period: null,
    pmin: Infinity, pmax: -Infinity, pcum: 0, prevP: null,
    prevX: null, prevY: null, speeds: []
  });
}

let bad = null;
let frames = 0;
for (let k = 0; k * DT <= SPAN; k++) {
  const t = k * DT;
  const bs = positions(t);
  const pos = new Map();
  for (const b of bs) pos.set(String(b.id), b);
  for (const b of bs) {
    const m = meta.get(String(b.id));
    if (!m) continue;
    const x = Number(b.x), y = Number(b.y), r = Number(b.r);
    if (!Number.isFinite(x) || !Number.isFinite(y) || !Number.isFinite(r) || r <= 0) {
      if (!bad) bad = m.id;
      continue;
    }
    const d = Math.hypot(x, y);
    if (d < m.rmin) m.rmin = d;
    if (d > m.rmax) m.rmax = d;
    m.dsum += d;
    const a = Math.atan2(y, x);
    if (m.prevA !== null) {
      m.cum += wrap(a - m.prevA);
      if (m.period === null && Math.abs(m.cum) >= TWO_PI) m.period = t;
    }
    m.prevA = a;
    if (m.prevX !== null && m.kind === 'comet') {
      m.speeds.push([d, Math.hypot(x - m.prevX, y - m.prevY) / DT]);
    }
    m.prevX = x; m.prevY = y;
    if (m.kind === 'moon' && m.parent && pos.has(m.parent)) {
      const p = pos.get(m.parent);
      const sx = x - Number(p.x), sy = y - Number(p.y);
      const sep = Math.hypot(sx, sy);
      if (sep < m.pmin) m.pmin = sep;
      if (sep > m.pmax) m.pmax = sep;
      const pa = Math.atan2(sy, sx);
      if (m.prevP !== null) m.pcum += wrap(pa - m.prevP);
      m.prevP = pa;
    }
  }
  frames++;
}

const out = { n: first.length, bad: bad, frames: frames, span: SPAN, bodies: [] };
for (const m of meta.values()) {
  const o = {
    id: m.id, kind: m.kind, parent: m.parent, r: m.r,
    rmin: m.rmin, rmax: m.rmax, mean: m.dsum / frames,
    period: m.period, revs: Math.abs(m.cum) / TWO_PI
  };
  if (m.kind === 'moon') {
    o.pmin = m.pmin; o.pmax = m.pmax; o.prevs = Math.abs(m.pcum) / TWO_PI;
  }
  if (m.kind === 'comet' && m.speeds.length) {
    const s = m.speeds.slice().sort((p, q) => p[0] - q[0]);
    const k = Math.max(1, Math.floor(s.length * 0.1));
    const avg = (arr) => arr.reduce((acc, p) => acc + p[1], 0) / arr.length;
    o.near = avg(s.slice(0, k));
    o.far = avg(s.slice(s.length - k));
  }
  out.bodies.push(o);
}
console.log(JSON.stringify(out));
"""


def node():
    return shutil.which("node") or shutil.which("node.exe")


class Acceptance(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.raw = TARGET.read_text(encoding="utf-8")
        cls.model = cls.extract_model(cls.raw)
        cls.data = cls.run_model(cls.model) if cls.model and node() else None

    @staticmethod
    def extract_model(raw):
        m = re.search(r'<script[^>]*id=["\']%s["\'][^>]*>(.*?)</script>' % MODEL_ID,
                      raw, re.S | re.I)
        return m.group(1) if m else None

    @staticmethod
    def run_model(src):
        with tempfile.TemporaryDirectory() as tmp:
            d = Path(tmp)
            (d / "model.mjs").write_text(src, encoding="utf-8")
            (d / "driver.mjs").write_text(DRIVER, encoding="utf-8")
            done = subprocess.run([node(), str(d / "driver.mjs")], capture_output=True,
                                  text=True, timeout=120, cwd=d)
            if done.returncode != 0:
                raise AssertionError("model failed in node: %s" % done.stderr[-800:])
            return json.loads(done.stdout.strip().splitlines()[-1])

    def model_data(self):
        self.assertIsNotNone(self.model,
                             'no <script id="%s"> block found' % MODEL_ID)
        if node() is None:
            raise unittest.SkipTest("node is required to measure the model")
        self.assertIsNotNone(self.data, "model produced no data")
        return self.data

    def kind(self, want):
        return [b for b in self.model_data()["bodies"] if b["kind"] == want]

    def planets(self):
        found = self.kind("planet")
        self.assertTrue(found, "no bodies of kind 'planet'")
        return sorted(found, key=lambda b: b["mean"])

    # --- the page itself -------------------------------------------------
    def test_is_one_self_contained_html_page(self):
        self.assertRegex(self.raw[:400].lower(), r"<!doctype html")
        self.assertIn("<canvas", self.raw.lower())

    def test_no_external_requests(self):
        for pat, why in ((r'src\s*=\s*["\'](https?:)?//', "external src"),
                         (r'href\s*=\s*["\'](https?:)?//', "external href"),
                         (r"@import", "css @import"),
                         (r'url\(\s*["\']?(https?:)?//', "external url()"),
                         (r"\bfetch\s*\(", "network fetch"),
                         (r"XMLHttpRequest", "XHR")):
            self.assertIsNone(re.search(pat, self.raw, re.I),
                              "page must be self-contained: found %s" % why)

    def test_animates_with_request_animation_frame(self):
        self.assertIn("requestAnimationFrame", self.raw)

    def test_model_is_separate_from_the_renderer(self):
        self.assertIsNotNone(self.model,
                             'the pure model must live in <script id="%s">' % MODEL_ID)
        for banned in ("getContext", "document.", "window.", "canvas"):
            self.assertNotIn(banned, self.model,
                             "model script must be pure math, found %r" % banned)

    # --- the system, measured --------------------------------------------
    def test_every_body_is_finite_and_sized(self):
        data = self.model_data()
        self.assertIsNone(data["bad"],
                          "body %r has a non-finite position or a radius <= 0" % data["bad"])
        ids = [b["id"] for b in data["bodies"]]
        self.assertEqual(len(set(ids)), len(ids), "body ids must be unique: %s" % ids)
        for b in data["bodies"]:
            self.assertLess(b["rmax"], 1e6, "%s flies out of range" % b["id"])

    def test_one_star_sits_at_the_centre(self):
        stars = self.kind("star")
        self.assertEqual(len(stars), 1, "exactly one body of kind 'star', got %d" % len(stars))
        star = stars[0]
        inner = self.planets()[0]
        self.assertLessEqual(star["rmax"], 0.02 * inner["rmin"],
                             "the star must hold the centre: it wanders to %.4f" % star["rmax"])
        biggest = max(b["r"] for b in self.model_data()["bodies"])
        self.assertEqual(star["r"], biggest,
                         "the star must be the largest body: r=%s vs %s" % (star["r"], biggest))

    def test_six_planets_a_moon_and_a_comet(self):
        self.assertGreaterEqual(len(self.kind("planet")), 6,
                                "need >=6 planets, got %d" % len(self.kind("planet")))
        self.assertGreaterEqual(len(self.kind("moon")), 1, "need at least one moon")
        self.assertGreaterEqual(len(self.kind("comet")), 1, "need at least one comet")

    def test_planet_orbits_do_not_cross(self):
        ps = self.planets()
        for a, b in zip(ps, ps[1:]):
            self.assertLess(a["rmax"], b["rmin"],
                            "%s (aphelion %.3f) crosses %s (perihelion %.3f)"
                            % (a["id"], a["rmax"], b["id"], b["rmin"]))

    def test_planet_orbits_are_ellipses(self):
        for p in self.planets():
            ratio = p["rmax"] / p["rmin"]
            self.assertGreaterEqual(ratio, 1.02,
                                    "%s traces a circle, not an ellipse (%.4f)" % (p["id"], ratio))
            self.assertLessEqual(ratio, 1.80,
                                 "%s is too eccentric for a planet (%.4f)" % (p["id"], ratio))

    def test_outer_planets_orbit_slower(self):
        ps = self.planets()
        for p in ps:
            self.assertIsNotNone(p["period"],
                                 "%s never completed an orbit in %ss" % (p["id"], self.data["span"]))
        for a, b in zip(ps, ps[1:]):
            self.assertLess(a["period"], b["period"],
                            "%s (a=%.3f, T=%.2fs) is not faster than %s (a=%.3f, T=%.2fs)"
                            % (a["id"], a["mean"], a["period"], b["id"], b["mean"], b["period"]))

    def test_periods_grow_faster_than_distance(self):
        """Kepler's third law in weak form: T scales with a^1.5, so the period ratio
        must beat the distance ratio. Uniform angular speed or uniform linear speed
        both fail this."""
        ps = self.planets()
        inner, outer = ps[0], ps[-1]
        span = outer["mean"] / inner["mean"]
        got = outer["period"] / inner["period"]
        self.assertGreater(got, 1.15 * span,
                           "not Kepler-like: %.2fx the distance but only %.2fx the period"
                           % (span, got))

    def test_the_moon_orbits_its_planet(self):
        planets = {p["id"]: p for p in self.planets()}
        for m in self.kind("moon"):
            host = planets.get(m["parent"])
            self.assertIsNotNone(host, "moon %s names no planet as parent (%r)"
                                 % (m["id"], m["parent"]))
            self.assertGreater(m["pmin"], 0, "%s sits on top of %s" % (m["id"], host["id"]))
            self.assertLess(m["pmax"], 0.3 * host["rmin"],
                            "%s strays %.3f from %s, too far to be its moon"
                            % (m["id"], m["pmax"], host["id"]))
            self.assertGreater(m["prevs"], host["revs"],
                               "%s must circle %s more often than %s circles the star"
                               % (m["id"], host["id"], host["id"]))

    def test_the_comet_is_visibly_eccentric(self):
        for c in self.kind("comet"):
            ratio = c["rmax"] / c["rmin"]
            self.assertGreaterEqual(ratio, 3.0,
                                    "comet %s is nearly circular: aphelion/perihelion %.2f"
                                    % (c["id"], ratio))

    def test_the_comet_speeds_up_near_the_star(self):
        """Kepler's second law: equal areas in equal times, so the comet must be far
        quicker at perihelion than at aphelion."""
        for c in self.kind("comet"):
            self.assertIn("near", c, "comet %s produced no speed samples" % c["id"])
            self.assertGreaterEqual(c["near"], 2.0 * c["far"],
                                    "comet %s barely accelerates: %.4f near vs %.4f far"
                                    % (c["id"], c["near"], c["far"]))


if __name__ == "__main__":
    unittest.main()
